(()=>{
const canvases=[...document.querySelectorAll('.fx-canvas[data-effect="steam"]')];if(!canvases.length)return;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,DPR=Math.min(devicePixelRatio||1,1.35),states=[];
function init(c){const ctx=c.getContext('2d',{alpha:true}),s={c,ctx,w:1,h:1,cols:0,rows:0,u:null,v:null,d:null,u2:null,v2:null,d2:null,last:performance.now(),pointer:null,profile:c.dataset.profile};resize(s);states.push(s);return s}
function resize(s){const r=s.c.getBoundingClientRect();s.w=Math.max(1,r.width);s.h=Math.max(1,r.height);s.c.width=Math.round(s.w*DPR);s.c.height=Math.round(s.h*DPR);s.ctx.setTransform(DPR,0,0,DPR,0,0);s.cols=s.w<700?54:78;s.rows=Math.round(s.cols*s.h/s.w);const n=s.cols*s.rows;s.u=new Float32Array(n);s.v=new Float32Array(n);s.d=new Float32Array(n);s.u2=new Float32Array(n);s.v2=new Float32Array(n);s.d2=new Float32Array(n)}
const id=(s,x,y)=>Math.max(0,Math.min(s.cols-1,x))+Math.max(0,Math.min(s.rows-1,y))*s.cols;
function splat(s,px,py,fx,fy,amount,radius=.055){const gx=px*s.cols,gy=py*s.rows,rr=Math.max(2,radius*s.cols);for(let y=Math.max(1,gy-rr|0);y<Math.min(s.rows-1,gy+rr);y++)for(let x=Math.max(1,gx-rr|0);x<Math.min(s.cols-1,gx+rr);x++){const dx=x-gx,dy=y-gy,q=(dx*dx+dy*dy)/(rr*rr);if(q<1){const k=Math.exp(-q*3.4),i=id(s,x,y);s.d[i]=Math.min(1.6,s.d[i]+amount*k);s.u[i]+=fx*k;s.v[i]+=fy*k}}}
function source(s,t){const mobile=s.w<700;const p=s.profile==='tsubasa'?{x:mobile?.49:.57,y:mobile?.50:.49}:{x:mobile?.51:.56,y:mobile?.49:.47};for(let j=0;j<3;j++){const a=t*.00035+j*2.1;splat(s,p.x+Math.sin(a)*.035,p.y+Math.cos(a*.73)*.012,Math.sin(a*1.7)*.012,-.055,.17,.048)}}
function step(s,dt){const C=s.cols,R=s.rows,n=C*R,u=s.u,v=s.v,d=s.d,u2=s.u2,v2=s.v2,d2=s.d2;for(let y=1;y<R-1;y++)for(let x=1;x<C-1;x++){const i=x+y*C;u[i]=(u[i]*.985+(u[i-1]+u[i+1]+u[i-C]+u[i+C])*.0037);v[i]=(v[i]*.985+(v[i-1]+v[i+1]+v[i-C]+v[i+C])*.0037)-.0018;d[i]=(d[i]*.986+(d[i-1]+d[i+1]+d[i-C]+d[i+C])*.0028)}for(let y=1;y<R-1;y++)for(let x=1;x<C-1;x++){const i=x+y*C,bx=Math.max(.5,Math.min(C-1.5,x-u[i]*dt*70)),by=Math.max(.5,Math.min(R-1.5,y-v[i]*dt*70)),x0=bx|0,y0=by|0,tx=bx-x0,ty=by-y0;const sm=(a)=>a[id(s,x0,y0)]*(1-tx)*(1-ty)+a[id(s,x0+1,y0)]*tx*(1-ty)+a[id(s,x0,y0+1)]*(1-tx)*ty+a[id(s,x0+1,y0+1)]*tx*ty;u2[i]=sm(u);v2[i]=sm(v);d2[i]=sm(d)}s.u=u2;s.u2=u;s.v=v2;s.v2=v;s.d=d2;s.d2=d}
function draw(s){const {ctx,w,h,cols:C,rows:R,d}=s;ctx.clearRect(0,0,w,h);const cw=w/C,ch=h/R;ctx.save();ctx.globalCompositeOperation='screen';ctx.filter='blur(8px)';for(let y=0;y<R;y+=2)for(let x=0;x<C;x+=2){const q=d[x+y*C];if(q>.025){const a=Math.min(.19,q*.13);ctx.fillStyle=`rgba(238,244,246,${a})`;ctx.beginPath();ctx.ellipse((x+.5)*cw,(y+.5)*ch,cw*2.4,ch*2.8,0,0,Math.PI*2);ctx.fill()}}ctx.restore()}
for(const c of canvases){const s=init(c);let down=false,last=null;const pos=e=>{const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}};c.style.pointerEvents='auto';c.addEventListener('pointerdown',e=>{down=true;last=pos(e);c.setPointerCapture?.(e.pointerId)});c.addEventListener('pointerup',()=>{down=false;last=null});c.addEventListener('pointermove',e=>{const p=pos(e);if(last){splat(s,p.x,p.y,(p.x-last.x)*2.8,(p.y-last.y)*2.8,.42,.065)}else splat(s,p.x,p.y,0,-.012,.09,.04);last=p;if(!down)setTimeout(()=>{last=null},80)},{passive:true})}
addEventListener('resize',()=>states.forEach(resize),{passive:true});
function frame(t){for(const s of states){const dt=Math.min(.032,(t-s.last)/1000||.016);s.last=t;source(s,reduced?2000:t);if(!reduced)step(s,dt);draw(s)}if(!reduced)requestAnimationFrame(frame)}requestAnimationFrame(frame);
window.__tsubasaEffects={isolated:true,disabledForPerformance:false,effects:['fluid-steam'],engine:'stable-fluids-inspired',interactive:true,canvasCount:states.length};
})();